        "(a+b)%768": lambda a,b,n,i,d: (a + b) % 768,
    },
    "⊠": {
        "a+b+n": lambda a,b,n,i,d: a + b + n,
        "a+b+2+2*d": lambda a,b,n,i,d: a + b + 2 + 2 * d,
        "a+b+n+i-1": lambda a,b,n,i,d: a + b + n + i - 1,
        "a+b+n*i": lambda a,b,n,i,d: a + b + n * i,
