def solve_all(ops_map):
    syms = list(ops_map.keys())
    counts = {}
    for pid, p in puzzles.items():
        nums, target = p["numbers"], p["target"]
        x1, x2, x3, x4 = nums
        c = 0
        for o1, o2, o3 in itertools.product(syms, repeat=3):
            f1, f2, f3 = ops_map[o1], ops_map[o2], ops_map[o3]
            for v in [
                f3(f2(f1(x1,x2,4,1,2), x3,4,2,1), x4,4,3,0),
                f3(f1(x1, f2(x2,x3,4,2,2),4,1,1), x4,4,3,0),
                f2(f1(x1,x2,4,1,1), f3(x3,x4,4,3,1),4,2,0),
                f1(x1, f3(f2(x2,x3,4,2,2), x4,4,3,1),4,1,0),
                f1(x1, f2(x2, f3(x3,x4,4,3,2),4,2,1),4,1,0),
            ]:
                if v == target:
                    c += 1
        counts[pid] = c
    return counts

